from fractions import Fraction

def simplest_between(lo, hi, lo_incl=True, hi_incl=True):
    # ---------- validation ----------
    if type(lo_incl) is not bool or type(hi_incl) is not bool:
        raise ValueError("lo_incl and hi_incl must be bool")
    if type(lo) is bool or type(hi) is bool:
        raise ValueError("lo and hi must not be bool")
    if not isinstance(lo, (int, Fraction)) or not isinstance(hi, (int, Fraction)):
        raise ValueError("lo and hi must be int or Fraction")

    lo = Fraction(lo)
    hi = Fraction(hi)

    if lo > hi:
        raise ValueError("lo must be <= hi")
    if lo == hi and not (lo_incl and hi_incl):
        raise ValueError("Interval is empty")

    # If the interval contains 0, 0 is the simplest.
    zero_in = (lo < 0 < hi) or (lo == 0 and lo_incl) or (hi == 0 and hi_incl)
    if zero_in:
        return Fraction(0)

    # Work with positive intervals by symmetry.
    if lo < 0 and hi < 0:
        res = _simplest_positive(-hi, -lo, hi_incl, lo_incl)
        return Fraction(-res.numerator, res.denominator)
    else:
        return _simplest_positive(lo, hi, lo_incl, hi_incl)


def _simplest_positive(lo, hi, lo_incl, hi_incl):
    """Return simplest fraction in [lo,hi] (or open endpoints), 0 <= lo <= hi."""
    if lo == hi:
        return lo

    # Find the smallest integer that is actually inside the interval.
    start = _ceil_include(lo, lo_incl)
    end = _floor_include(hi, hi_incl)
    if start <= end:
        return Fraction(start)

    # No integer inside.  Both endpoints lie between the same consecutive
    # integers k and k+1, with endpoints possibly excluded.
    k = lo.numerator // lo.denominator          # floor(lo)

    a = lo - k          # fractional part of lo
    b = hi - k          # fractional part of hi
    # 0 <= a <= b <= 1, and 0 is not included, 1 is not included.

    # If a == 0, the reciprocal interval is unbounded above.
    if a == 0:  # lo_incl must be False
        # t in (0, b] or (0,b).  s = 1/t in [1/b, ∞) or (1/b, ∞).
        # The simplest fraction there is the smallest integer inside.
        n = _ceil_include(Fraction(1, b), hi_incl)
        return Fraction(k * n + 1, n)

    # If b == 1, handle via a bounded reciprocal interval.
    if b == 1:  # hi_incl must be False
        # t in [a,1) or (a,1).  s = 1/t in (1, 1/a] or (1, 1/a).
        # Left endpoint 1 is excluded; right endpoint depends on lo_incl.
        res = _simplest_positive(Fraction(1), Fraction(1, a),
                                 False, lo_incl)
        # res = p/q, t = q/p, r = k + q/p
        return Fraction(k * res.numerator + res.denominator,
                        res.numerator)

    # Now 0 < a < b < 1.  Reciprocal interval is bounded.
    rec_lo = Fraction(1, b)   # 1/b
    rec_hi = Fraction(1, a)   # 1/a
    # Flags swap: left endpoint corresponds to hi, right to lo.
    res = _simplest_positive(rec_lo, rec_hi, hi_incl, lo_incl)
    # res = p/q, t = q/p, r = k + q/p
    return Fraction(k * res.numerator + res.denominator,
                    res.numerator)


def _ceil_include(x, incl):
    """Smallest integer n >= x if incl, else n > x."""
    if x.denominator == 1:
        return x.numerator if incl else x.numerator + 1
    else:
        return x.numerator // x.denominator + 1


def _floor_include(x, incl):
    """Largest integer n <= x if incl, else n < x."""
    if x.denominator == 1:
        return x.numerator if incl else x.numerator - 1
    else:
        return x.numerator // x.denominator

from fractions import Fraction

def simplest_between(lo, hi, lo_incl=True, hi_incl=True):
    """Return the simplest fraction in the interval from lo to hi."""
    # ---------- type checks ----------
    if type(lo_incl) is not bool or type(hi_incl) is not bool:
        raise ValueError("lo_incl and hi_incl must be bool")
    if type(lo) is bool or type(hi) is bool:
        raise ValueError("lo and hi must not be bool")
    if not isinstance(lo, (int, Fraction)) or not isinstance(hi, (int, Fraction)):
        raise ValueError("lo and hi must be int or Fraction")

    lo = Fraction(lo)
    hi = Fraction(hi)

    if lo > hi:
        raise ValueError("lo must be <= hi")
    if lo == hi and not (lo_incl and hi_incl):
        raise ValueError("Interval is empty")

    # ---------- 0 in interval? ----------
    if (lo < 0 < hi) or (lo == 0 and lo_incl) or (hi == 0 and hi_incl):
        return Fraction(0)

    # ---------- negative interval: mirror to positive ----------
    if hi < 0 or (hi == 0 and not hi_incl):
        # x in [lo, hi]  <=>  -x in [-hi, -lo]
        res = _simplest_positive(-hi, -lo, hi_incl, lo_incl)
        return Fraction(-res.numerator, res.denominator)

    # Now interval is positive (0 is excluded and lo >= 0).
    return _simplest_positive(lo, hi, lo_incl, hi_incl)


def _simplest_positive(lo, hi, lo_incl, hi_incl):
    """Find simplest fraction in a non-negative interval, 0 not included."""
    # Check for an integer inside; return the one closest to 0.
    n = lo.numerator // lo.denominator  # floor(lo)

    if lo.denominator == 1 and lo_incl:
        k = lo.numerator
    else:
        k = n + 1

    if k < hi or (k == hi and hi_incl):
        return Fraction(k)

    # No integer inside: the interval lies inside one unit interval [n, n+1].
    a = lo - n
    b = hi - n

    # Special case: interval starts at 0, with 0 excluded.
    if a == 0 and not lo_incl:
        # Interval is (0, b] or (0, b), with b <= 1 and b not an integer
        # unless b=1 excluded (handled by integer check).
        q = b.denominator // b.numerator + 1  # floor(1/b) + 1
        cand = Fraction(1, q)

        if hi_incl and b.denominator < cand.denominator:
            return n + b
        return n + cand

    # General case: 0 < a <= b < 1, or endpoints may be included.
    # Use reciprocal: y in (a,b)  <=>  z = 1/y in (1/b, 1/a).
    rec_lo = Fraction(1, b)
    rec_hi = Fraction(1, a)
    rec_lo_incl = hi_incl
    rec_hi_incl = lo_incl

    w = _simplest_positive(rec_lo, rec_hi, rec_lo_incl, rec_hi_incl)

    # w = 1/y, so y = 1/w.
    y = Fraction(w.denominator, w.numerator)
    return n + y

import bisect

def staircase_log(points):
    # Validation
    if not isinstance(points, (list, tuple)):
        raise ValueError("points must be a list or tuple")
    for p in points:
        if not isinstance(p, (list, tuple)) or len(p) != 2:
            raise ValueError("Each point must be a list or tuple of two ints")
        x, y = p
        if isinstance(x, bool) or isinstance(y, bool):
            raise ValueError("Coordinates must be ints, not bools")
        if not isinstance(x, int) or not isinstance(y, int):
            raise ValueError("Coordinates must be ints")

    flags = []
    front = []          # list of tuples (x, y), sorted by x, y strictly decreasing
    front_xs = []       # parallel list of x values

    for p in points:
        x, y = p

        # Find first index with front_xs >= x
        idx = bisect.bisect_left(front_xs, x)

        # Check domination by an earlier point
        dominated = False
        if idx < len(front):
            qx, qy = front[idx]
            if qx == x:
                if qy > y:
                    dominated = True
            else:  # qx > x
                if qy >= y:
                    dominated = True

        if dominated:
            flags.append(False)
            continue

        # Check exact duplicate (not dominated by itself)
        if idx < len(front) and front[idx][0] == x and front[idx][1] == y:
            flags.append(True)
            continue

        # Not dominated and not a duplicate: insert, removing dominated points
        # Determine the rightmost index that might be dominated
        if idx < len(front) and front[idx][0] == x:
            scan_start = idx          # same x, must have y < y (else it would dominate)
        else:
            scan_start = idx - 1      # only points with x < x can be dominated

        # Scan leftwards while y <= current y
        remove_end = scan_start
        while remove_end >= 0 and front[remove_end][1] <= y:
            remove_end -= 1

        remove_start = remove_end + 1
        if remove_start <= scan_start:
            del front[remove_start:scan_start + 1]
            del front_xs[remove_start:scan_start + 1]
            insert_pos = remove_start
        else:
            insert_pos = scan_start + 1

        front.insert(insert_pos, (x, y))
        front_xs.insert(insert_pos, x)
        flags.append(True)

    return flags, front

