def mlfq_finish_times(jobs, quanta):
    # Validation
    if not isinstance(jobs, list):
        raise ValueError("jobs must be a list")
    if not isinstance(quanta, list):
        raise ValueError("quanta must be a list")
    if len(quanta) < 1 or len(quanta) > 5:
        raise ValueError("quanta must have 1 to 5 elements")
    for q in quanta:
        if isinstance(q, bool) or not isinstance(q, int) or q < 1 or q > 10000:
            raise ValueError("invalid quantum")
    if len(jobs) > 100:
        raise ValueError("too many jobs")

    n = len(jobs)
    for job in jobs:
        if not isinstance(job, (list, tuple)) or len(job) != 2:
            raise ValueError("each job must be an (arrival, burst) pair")
        arr, burst = job
        if isinstance(arr, bool) or not isinstance(arr, int):
            raise ValueError("arrival must be an int")
        if isinstance(burst, bool) or not isinstance(burst, int):
            raise ValueError("burst must be an int")
        if arr < 0 or arr > 1000000 or burst < 1 or burst > 10000:
            raise ValueError("invalid job parameters")

    if n == 0:
        return []

    # Arrivals sorted by time, then original input order.
    arrivals = []
    for i in range(n):
        arrivals.append((jobs[i][0], i))
    arrivals.sort(key=lambda x: (x[0], x[1]))

    queues = [collections.deque() for _ in range(len(quanta))]
    remaining = [jobs[i][1] for i in range(n)]
    finish = [0] * n
    finished = 0

    current_job = -1
    current_level = -1
    quantum_left = 0

    time = 0
    arr_ptr = 0

    while finished < n:
        next_arrival = float('inf')
        if arr_ptr < n:
            next_arrival = arrivals[arr_ptr][0]

        preempt = False

        if current_job != -1:
            # Scheduled end of the current run.
            run_end = time + min(quantum_left, remaining[current_job])

            # A level >= 1 job is preempted by an arrival strictly inside its run.
            if current_level >= 1 and next_arrival > time and next_arrival < run_end:
                preempt = True
                next_time = next_arrival
            else:
                next_time = min(next_arrival, run_end)
        else:
            # CPU idles until the next arrival.
            next_time = next_arrival

        if next_time == float('inf'):
            break

        duration = next_time - time
        time = next_time

        if duration > 0 and current_job != -1:
            remaining[current_job] -= duration
            quantum_left -= duration

        # Queue all arrivals at this instant, in input order.
        while arr_ptr < n and arrivals[arr_ptr][0] == time:
            idx = arrivals[arr_ptr][1]
            queues[0].append(idx)
            arr_ptr += 1

        # Handle the job that was running.
        if current_job != -1:
            if preempt:
                # Preempted: go to the FRONT of its own level.
                queues[current_level].appendleft(current_job)
                current_job = -1
                current_level = -1
                quantum_left = 0
            else:
                if remaining[current_job] <= 0:
                    finish[current_job] = time
                    finished += 1
                    current_job = -1
                    current_level = -1
                    quantum_left = 0
                elif quantum_left <= 0:
                    # Demote after arrivals have already been queued.
                    if current_level < len(quanta) - 1:
                        queues[current_level + 1].append(current_job)
                    else:
                        queues[current_level].append(current_job)
                    current_job = -1
                    current_level = -1
                    quantum_left = 0
                # Otherwise the job continues; nothing else changes.

        # Pick the next job if the CPU is free.
        if current_job == -1:
            for level in range(len(quanta)):
                if queues[level]:
                    current_job = queues[level].popleft()
                    current_level = level
                    quantum_left = quanta[level]
                    break

    return finish

def rank_mini_league(results):
    # Input validation
    if not isinstance(results, list):
        raise ValueError("Input must be a list")
    if len(results) > 400:
        raise ValueError("Too many matches")

    matches = []
    teams = set()

    for match in results:
        if not isinstance(match, (list, tuple)) or len(match) != 4:
            raise ValueError("Each match must be a tuple/list of 4 elements")

        h, a, hg, ag = match

        if not isinstance(h, str) or len(h) == 0:
            raise ValueError("Home team must be a non-empty string")
        if not isinstance(a, str) or len(a) == 0:
            raise ValueError("Away team must be a non-empty string")
        if h == a:
            raise ValueError("Home and away teams must be different")

        # Strictly int, not bool; bool is not accepted as an int here.
        if type(hg) is not int or type(ag) is not int:
            raise ValueError("Goals must be integers")
        if not (0 <= hg <= 99) or not (0 <= ag <= 99):
            raise ValueError("Goals must be between 0 and 99")

        matches.append((h, a, hg, ag))
        teams.add(h)
        teams.add(a)

    if not teams:
        return []

    # Overall statistics
    global_points = {t: 0 for t in teams}
    global_gs = {t: 0 for t in teams}
    global_gc = {t: 0 for t in teams}

    for h, a, hg, ag in matches:
        global_gs[h] += hg
        global_gc[h] += ag
        global_gs[a] += ag
        global_gc[a] += hg

        if hg > ag:
            global_points[h] += 3
        elif hg == ag:
            global_points[h] += 1
            global_points[a] += 1
        else:
            global_points[a] += 3

    # Group teams by total points
    points_groups = {}
    for t in teams:
        points_groups.setdefault(global_points[t], []).append(t)

    final_order = []

    # Process groups from highest points to lowest
    for pts in sorted(points_groups.keys(), reverse=True):
        group_teams = points_groups[pts]

        # Mini-table matches: only matches where both teams are in this group
        group_matches = [
            m for m in matches
            if m[0] in group_teams and m[1] in group_teams
        ]

        mini_pts = {t: 0 for t in group_teams}
        mini_gs = {t: 0 for t in group_teams}
        mini_gc = {t: 0 for t in group_teams}
        mini_awg = {t: 0 for t in group_teams}

        for h, a, hg, ag in group_matches:
            if hg > ag:
                mini_pts[h] += 3
            elif hg == ag:
                mini_pts[h] += 1
                mini_pts[a] += 1
            else:
                mini_pts[a] += 3

            mini_gs[h] += hg
            mini_gc[h] += ag
            mini_gs[a] += ag
            mini_gc[a] += hg

            # Away goals: goals scored by the away team
            mini_awg[a] += ag

        mini_gd = {t: mini_gs[t] - mini_gc[t] for t in group_teams}

        def sort_key(t):
            ogd = global_gs[t] - global_gc[t]
            ogs = global_gs[t]
            return (
                -mini_pts[t],
                -mini_gd[t],
                -mini_gs[t],
                -mini_awg[t],
                -ogd,
                -ogs,
                t,
            )

        final_order.extend(sorted(group_teams, key=sort_key))

    return final_order

def replay_editor_log(commands):
    if not isinstance(commands, list):
        raise ValueError
    if len(commands) > 2000:
        raise ValueError

    text = ""
    cursor = 0
    undo_stack = []
    redo_stack = []
    current_group = None

    for cmd in commands:
        if not isinstance(cmd, (tuple, list)) or len(cmd) == 0:
            raise ValueError
        name = cmd[0]

        if name == "type":
            if len(cmd) != 2 or not isinstance(cmd[1], str) or not (1 <= len(cmd[1]) <= 20):
                raise ValueError
        elif name in ("back", "del", "left", "right"):
            if len(cmd) != 2:
                raise ValueError
            n = cmd[1]
            if isinstance(n, bool) or not isinstance(n, int):
                raise ValueError
            if not (1 <= n <= 10**6):
                raise ValueError
        elif name in ("home", "end", "undo", "redo"):
            if len(cmd) != 1:
                raise ValueError
        else:
            raise ValueError

        # Only a "type" command can extend an existing type run.
        extends_current = (name == "type" and current_group is not None and current_group.get('kind') == 'type')

        # Commit any pending group that this command does not extend.
        if current_group is not None and not extends_current:
            undo_stack.append(current_group)
            current_group = None

        old_text = text
        old_cursor = cursor

        if name == "type":
            s = cmd[1]
            text = text[:cursor] + s + text[cursor:]
            cursor += len(s)
            if current_group is None:
                current_group = {'kind': 'type', 'tb': old_text, 'cb': old_cursor, 'ta': text, 'ca': cursor}
            else:
                current_group['ta'] = text
                current_group['ca'] = cursor
            redo_stack.clear()

        elif name == "back":
            n = cmd[1]
            del_count = min(n, cursor)
            text = text[:cursor - del_count] + text[cursor:]
            cursor -= del_count
            if del_count > 0:
                current_group = {'kind': 'single', 'tb': old_text, 'cb': old_cursor, 'ta': text, 'ca': cursor}
                redo_stack.clear()

        elif name == "del":
            n = cmd[1]
            del_count = min(n, len(text) - cursor)
            text = text[:cursor] + text[cursor + del_count:]
            if del_count > 0:
                current_group = {'kind': 'single', 'tb': old_text, 'cb': old_cursor, 'ta': text, 'ca': cursor}
                redo_stack.clear()

        elif name == "left":
            n = cmd[1]
            cursor = max(0, cursor - n)

        elif name == "right":
            n = cmd[1]
            cursor = min(len(text), cursor + n)

        elif name == "home":
            cursor = 0

        elif name == "end":
            cursor = len(text)

        elif name == "undo":
            group_to_undo = None
            if current_group is not None:
                group_to_undo = current_group
                current_group = None
            elif undo_stack:
                group_to_undo = undo_stack.pop()

            if group_to_undo is not None:
                text = group_to_undo['tb']
                cursor = group_to_undo['cb']
                redo_stack.append(group_to_undo)

        elif name == "redo":
            if redo_stack:
                group_to_redo = redo_stack.pop()
                text = group_to_redo['ta']
                cursor = group_to_redo['ca']
                undo_stack.append(group_to_redo)

    # Commit any remaining pending group
    if current_group is not None:
        undo_stack.append(current_group)

    return text, cursor, len(undo_stack), len(redo_stack)
